class Solution {
public:
    int numberOfWays(string corridor) {
        const long long MOD=1000000007;long long ans=1;
        int seats=0,prev=-1;
        for(int i=0;i<(int)corridor.size();++i) if(corridor[i]=='S') {
            if(seats>0 && seats%2==0) ans=ans*(i-prev)%MOD;
            ++seats;prev=i;
        }
        return seats>0 && seats%2==0 ? (int)ans : 0;
    }
};
